/**
 * Mirrors the engine's `error.*` i18n codes: the string the Kotlin layer
 * looks up in `strings.xml`. `Engine` reports `error.pdfBuild` — the
 * dominant collapsed source; the original detail rides in `detail`.
 */
sealed class FfiException: kotlin.Exception() {
    
    class MissingInput(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class InvalidPdf(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class InputTooLarge(
        
        val `sizeBytes`: kotlin.ULong, 
        
        val `limitBytes`: kotlin.ULong
        ) : FfiException() {
        override val message
            get() = "sizeBytes=${ `sizeBytes` }, limitBytes=${ `limitBytes` }"
    }
    
    class EncryptedPdf(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class PasswordRequired(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class WrongPassword(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class Cancelled(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class Engine(
        
        val `detail`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiException = FfiConverterTypeFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException> {
    override fun read(buf: ByteBuffer): FfiException {
        

        return when(buf.getInt()) {
            1 -> FfiException.MissingInput()
            2 -> FfiException.InvalidPdf()
            3 -> FfiException.InputTooLarge(
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            4 -> FfiException.EncryptedPdf()
            5 -> FfiException.PasswordRequired()
            6 -> FfiException.WrongPassword()
            7 -> FfiException.Cancelled()
            8 -> FfiException.Engine(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiException): ULong {
        return when(value) {
            is FfiException.MissingInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.InvalidPdf -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.InputTooLarge -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`sizeBytes`)
                + FfiConverterULong.allocationSize(value.`limitBytes`)
            )
            is FfiException.EncryptedPdf -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.PasswordRequired -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.WrongPassword -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.Cancelled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.Engine -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: FfiException, buf: ByteBuffer) {
        when(value) {
            is FfiException.MissingInput -> {
                buf.putInt(1)
                Unit
            }
            is FfiException.InvalidPdf -> {
                buf.putInt(2)
                Unit
            }
            is FfiException.InputTooLarge -> {
                buf.putInt(3)
                FfiConverterULong.write(value.`sizeBytes`, buf)
                FfiConverterULong.write(value.`limitBytes`, buf)
                Unit
            }
            is FfiException.EncryptedPdf -> {
                buf.putInt(4)
                Unit
            }
            is FfiException.PasswordRequired -> {
                buf.putInt(5)
                Unit
            }
            is FfiException.WrongPassword -> {
                buf.putInt(6)
                Unit
            }
            is FfiException.Cancelled -> {
                buf.putInt(7)
                Unit
            }
            is FfiException.Engine -> {
                buf.putInt(8)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





/**
 * Progress callback implemented on the Kotlin side. The engine already
 * throttles to 3% granularity — no extra layer here. Callbacks arrive on
 * whatever thread the engine reports from (its worker pool); UI updates
 * must hop to the main dispatcher on the Kotlin side.
 */
public interface FfiProgress {
    
    fun `onProgress`(`update`: FfiProgressUpdate)
    
    companion object
}



// Put the implementation in an object so we don't pollute the top-level namespace
internal object uniffiCallbackInterfaceFfiProgress {
    internal object `onProgress`: UniffiCallbackInterfaceFfiProgressMethod0 {
        override fun callback(`uniffiHandle`: Long,`update`: RustBuffer.ByValue,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeFfiProgress.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`onProgress`(
                    FfiConverterTypeFfiProgressUpdate.lift(`update`),
                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeFfiProgress.handleMap.remove(handle)
        }
    }

    internal object uniffiClone: UniffiCallbackInterfaceClone {
        override fun callback(handle: Long): Long {
            return FfiConverterTypeFfiProgress.handleMap.clone(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceFfiProgress.UniffiByValue(
        uniffiFree,
        uniffiClone,
        `onProgress`,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
    internal fun register(lib: UniffiLib) {
        lib.uniffi_pdf_core_ffi_fn_init_callback_vtable_ffiprogress(vtable)
    }
}

